package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.app.Activity; import android.view.WindowManager; @DesignerComponent(version = 1, description = "Custom WebViewer que se adapta ao teclado virtual para nao cobrir o conteudo.", category = ComponentCategory.EXTENSION, nonVisible = false) @SimpleObject(external = true) public class CustomAdaptiveWebViewer extends WebViewer { private Activity activity; public CustomAdaptiveWebViewer(ComponentContainer container) { super(container); this.activity = container.$context(); /* Define o redimensionamento da janela para nao cobrir o conteudo do webviewer */ this.activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Ativa a adaptacao ao teclado virtual.") public void AtivarAdaptacao() { this.activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Desativa a adaptacao ao teclado virtual.") public void DesativarAdaptacao() { this.activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } }); } }